python3 -c "
import json
with open('/app/resources/treasury_bulletin_2010_03.json', 'r') as f:
    data = json.load(f)

# Search for tables with March 2009 data
def find_in_elements(els, search_str):
    for el in els:
        content = el.get('content', '')
        if search_str in str(content):
            print('Found:', content[:500] if content else 'None')

for elem in data['document']['elements']:
    if elem.get('content'):
        content = str(elem['content'])
        if 'Mar' in content and '2009' in content:
            print('MARCH 2009:', content[:800])
        if 'Sep' in content and '2009' in content:
            print('SEPTEMBER 2009:', content[:800])
"
